insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('JP:carpenter','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 091-01 大工 directly covers building carpentry and apprentices.','entry_level_basis','Vocational, employer and supervised site training support practical entry.','market_scope','No exact recurring cross-country-comparable 091-01 market series has been normalised.','visa_scope','No occupation-specific visa credit is assigned.','score_scope','Entry accessibility and low universal licensing burden only.'),'2026-08-10'),
('JP:electrician','2026-08-10',0,0,0,0,12,0,0,0,1,13,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 094-05 電気工事作業員 is the direct building-electrical trade anchor.','entry_level_basis','Vocational electrical training and supervised practical experience support entry.','qualification_note','Statutory electrical work requires the applicable 電気工事士 qualification; education alone is insufficient.','market_scope','Exact recurring comparable 094-05 market evidence is not yet normalised.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:plumber','2026-08-10',0,0,0,0,15,0,0,0,4,19,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 091-06 配管工 directly covers water, gas, steam and air-conditioning piping.','entry_level_basis','Vocational and supervised practical routes support entry.','qualification_note','Regulated water-supply installation uses the designated-contractor and 給水装置工事主任技術者 framework, but the full plumber occupation is not universally licensed.','market_scope','Broad utility and construction observations are not substituted for exact plumber evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:wall-floor-tiler','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Tile work is a restricted subset of 2022 MHLW 091-02 ブロック積工、タイル張工.','entry_level_basis','Practical vocational and site-based entry is accessible.','market_scope','Whole-group masonry/tile observations are not treated as tile-only evidence.','visa_scope','No occupation-specific visa credit is assigned.','score_scope','Entry accessibility and low universal licensing burden only.'),'2026-08-10'),
('JP:welder','2026-08-10',0,0,0,0,15,0,0,0,3,18,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 071-13 金属溶接・溶断工 directly covers welding and thermal cutting work.','entry_level_basis','Practical process training is central to entry.','qualification_note','Gas welding requires prescribed skills training and arc-welding work requires statutory special education; this is process-specific rather than one universal welder licence.','market_scope','Construction and manufacturing demand are not blended into a fabricated welder-only score.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:bricklayer','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Brick and block masonry are a restricted subset of 2022 MHLW 091-02 ブロック積工、タイル張工.','entry_level_basis','Practical vocational and supervised site entry is accessible.','market_scope','Whole-group tile/masonry observations are not treated as bricklayer-only evidence.','visa_scope','No occupation-specific visa credit is assigned.','score_scope','Entry accessibility and low universal licensing burden only.'),'2026-08-10'),
('JP:hvac-technician','2026-08-10',0,0,0,0,12,0,0,0,4,16,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','The canonical HVAC technician spans 075-01 commercial HVAC/refrigeration repair, 075-02 household AC repair, 091-06 HVAC piping and 094-05 household AC electrical installation.','entry_level_basis','Technical training and supervised installation/maintenance experience support entry.','qualification_note','Electrical, refrigerant, piping and facility responsibilities can carry separate requirements; no single universal HVAC licence covers the whole umbrella.','market_scope','Incompatible source groups are not merged into one fabricated HVAC market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:construction-manager','2026-08-10',0,0,0,0,10,0,0,0,3,13,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 008-02 建築施工管理技術者 directly covers building construction management and site supervision.','entry_level_basis','Architecture/civil study is relevant, but progression is experience-sensitive; five approved Japanese programmes are retained only as related pathways.','qualification_note','No particular qualification is required merely to enter the occupation, while legally designated 主任技術者/監理技術者 appointments can require recognised qualifications or experience.','market_scope','Current job-tag figures are not yet normalised for cross-country scoring.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10')
